import{_ as a,o as t,c as o,a3 as r}from"./chunks/framework.DNWyyI0w.js";const u=JSON.parse('{"title":"Approval & Spend Guardrails","description":"","frontmatter":{},"headers":[],"relativePath":"guides/guardrails.md","filePath":"guides/guardrails.md"}'),n={name:"guides/guardrails.md"};function s(d,e,i,c,l,p){return t(),o("div",null,[...e[0]||(e[0]=[r(`<h1 id="approval-spend-guardrails" tabindex="-1">Approval &amp; Spend Guardrails <a class="header-anchor" href="#approval-spend-guardrails" aria-label="Permalink to &quot;Approval &amp; Spend Guardrails&quot;">​</a></h1><p>Saidi&#39;s guardrails are layered so that no single mistake — a bad plan, a runaway loop, a too-permissive agent — can turn into an expensive one.</p><h2 id="layer-1-the-approval-gate" tabindex="-1">Layer 1: the approval gate <a class="header-anchor" href="#layer-1-the-approval-gate" aria-label="Permalink to &quot;Layer 1: the approval gate&quot;">​</a></h2><p>Set per project, in <code>memory/projects/&lt;name&gt;.md</code>:</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">---</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">branch: new</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">approval: confirm</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">verify: npm run build &amp;&amp; npm test</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">---</span></span></code></pre></div><ul><li><strong><code>approval: confirm</code></strong> parks every write as a structured <code>PendingApproval</code>.</li><li><strong><code>branch: new</code></strong> means work lands on a <code>saidi/*</code> branch with a PR — never on your checked-out branch, and never merged for you.</li><li><strong><code>verify:</code></strong> runs after the commit and reports pass/fail mechanically.</li></ul><p>Unset or invalid values fall back to the safe policy (<code>new</code> + <code>confirm</code>). Change the operator-wide fallback in <strong>Settings → System</strong> if you need a different default, but raise it deliberately — this is the one dial that decides whether a model can write to your repo unattended.</p><h2 id="layer-2-auto-approve-scoped" tabindex="-1">Layer 2: auto-approve, scoped <a class="header-anchor" href="#layer-2-auto-approve-scoped" aria-label="Permalink to &quot;Layer 2: auto-approve, scoped&quot;">​</a></h2><p>Rather than switching a whole project to <code>approval: auto</code>, Settings exposes per-action auto-approval (<code>AutoApproveAction</code>). Grant the specific low-risk actions you are tired of clicking, and leave the rest gated. The narrower grant is almost always the right one.</p><h2 id="layer-3-agent-permissions" tabindex="-1">Layer 3: agent permissions <a class="header-anchor" href="#layer-3-agent-permissions" aria-label="Permalink to &quot;Layer 3: agent permissions&quot;">​</a></h2><p>An agent&#39;s <code>permission</code> (<code>all</code> / <code>read-only</code> / <code>custom</code>) is enforced by handing the SDK a restricted tool set with a <code>canUseTool</code> gate behind it. A <code>read-only</code> agent cannot write even inside a <code>work</code> delegation — the narrower of the two always wins.</p><p>For anything touching an external system, prefer <code>custom</code> with a short explicit <code>tools:</code> list over <code>all</code>.</p><h2 id="layer-4-spend" tabindex="-1">Layer 4: spend <a class="header-anchor" href="#layer-4-spend" aria-label="Permalink to &quot;Layer 4: spend&quot;">​</a></h2><p>Enforcement runs before a delegation is dispatched. It can:</p><ul><li><strong>Block</strong> the call when the operator&#39;s allowance is exhausted (<code>usageBlockReason</code>).</li><li><strong>Clamp the effort tier</strong> down instead of refusing, so a run degrades rather than dying (<code>clampEffort</code>).</li><li><strong>Deny agent access</strong> or a specific run action on a permission check.</li></ul><p>Everything spent is recorded per call in the run&#39;s <code>usageLog</code>, with <code>unpriced</code> flagged rather than silently counted as zero — a cap you cannot measure is not a cap.</p><h2 id="layer-5-attempt-budgets" tabindex="-1">Layer 5: attempt budgets <a class="header-anchor" href="#layer-5-attempt-budgets" aria-label="Permalink to &quot;Layer 5: attempt budgets&quot;">​</a></h2><ul><li>A <strong>global</strong> attempt ceiling applies to every task.</li><li>A <strong>per-task</strong> <code>attemptBudget</code> can lower it — and cannot exceed the global. A one-shot inbox lookup and a twenty-minute document rebuild should not get the same number of retries.</li><li><code>failureKind</code> routes the retry: <code>environment_failure</code> and <code>semantic_failure</code> do not deserve the same response, and treating every rejection as &quot;redo the whole task&quot; is how a budget disappears.</li></ul><h2 id="layer-6-concurrency-locks" tabindex="-1">Layer 6: concurrency locks <a class="header-anchor" href="#layer-6-concurrency-locks" aria-label="Permalink to &quot;Layer 6: concurrency locks&quot;">​</a></h2><p>A <strong>repo lock</strong> serialises delegations against one checkout; custom agents take an equivalent <strong>agent lock</strong>. Two runs cannot interleave commits on the same working directory. Custom agents also get a per-run <code>workDir</code>, so concurrent runs never share a directory.</p><h2 id="layer-7-reflex-controls" tabindex="-1">Layer 7: reflex controls <a class="header-anchor" href="#layer-7-reflex-controls" aria-label="Permalink to &quot;Layer 7: reflex controls&quot;">​</a></h2><p>For anything event-triggered, see <a href="./building-a-reflex">Building a Reflex</a>:</p><p><code>cooldownSec</code>, <code>dedupKey</code>, <code>maxFires</code>, <code>requireApproval</code>, <code>enabled</code>, plus a bus-level chain-depth cap on <code>emitEvent</code> chains.</p><h2 id="a-sane-starting-posture" tabindex="-1">A sane starting posture <a class="header-anchor" href="#a-sane-starting-posture" aria-label="Permalink to &quot;A sane starting posture&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Setting</th><th>Start at</th></tr></thead><tbody><tr><td>Project <code>approval</code></td><td><code>confirm</code></td></tr><tr><td>Project <code>branch</code></td><td><code>new</code></td></tr><tr><td>Project <code>verify</code></td><td>Your test command — always set this</td></tr><tr><td>New custom agent <code>permission</code></td><td><code>read-only</code>, widen only on evidence</td></tr><tr><td>Reflexes that write</td><td><code>requireApproval: true</code> + a <code>dedupKey</code> + <code>maxFires</code></td></tr><tr><td>Execution mode for repeatable work</td><td><code>guided</code></td></tr></tbody></table><p>Relax individual dials once you have watched them hold. Relax them one at a time, so you know which one was load-bearing.</p><p>See also: <a href="/docs/concepts/modes-and-permissions">Modes &amp; Permissions</a> · <a href="/docs/reference/project-policy">Project Policy</a></p>`,27)])])}const g=a(n,[["render",s]]);export{u as __pageData,g as default};
